def _key_transition(request: dict[str, Any]) -> dict[str, Any]:
    window = _resolve(request.get("target"))
    vk = int(request.get("vk") or 0)
    hwnd = int(window["hwnd"])
    physical = bool(request.get("physical", False))
    if physical:
        _focus(hwnd)
        u32 = ctypes.WinDLL("user32", use_last_error=True)
        u32.keybd_event(vk, 0, 0, 0)
        u32.keybd_event(vk, 0, 0x0002, 0)
    else:
        drive.press(hwnd, vk)
    return {"window": window, "pressed": vk, "physical": physical}
